"""Weekly timesheet lines built from a list of shifts."""

from typing import Dict, Iterable, List, Tuple
from hourglass.models import Shift
from hourglass.errors import ProjectError


def _check_shifts(shifts: List[Shift]) -> None:
    if not shifts:
        raise ProjectError("no shifts to build a timesheet from")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError(f"shift on {shift.day} has a blank worker name")


def _tally(shifts: Iterable[Shift]) -> Dict[str, Tuple[int, int]]:
    totals = {}
    for shift in shifts:
        count, minutes = totals.get(shift.worker, (0, 0))
        totals[shift.worker] = (count + 1, minutes + shift.span.minutes)
    return totals


def _format_line(name: str, count: int, minutes: int) -> str:
    noun = "shift" if count == 1 else "shifts"
    return f"{name}: {count} {noun}, {minutes / 60:.1f} hours"


# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first. ProjectError on bad input."""
    shifts = list(shifts)
    _check_shifts(shifts)
    totals = _tally(shifts)
    order = sorted(totals, key=lambda name: (-totals[name][1], name))
    return [_format_line(name, *totals[name]) for name in order]
